CREATE TABLE feeds (url TEXT PRIMARY KEY, checked_at INTEGER NOT NULL, error_code TEXT);
CREATE TABLE entries (
 feed TEXT NOT NULL, entry_key TEXT NOT NULL, title TEXT NOT NULL, link TEXT NOT NULL,
 published INTEGER NOT NULL, state TEXT NOT NULL, due INTEGER,
 PRIMARY KEY(feed,entry_key)
);

CREATE TABLE updates (id INTEGER PRIMARY KEY, response TEXT NOT NULL);
CREATE TABLE send_clock (id INTEGER PRIMARY KEY, attempted_at INTEGER NOT NULL);
INSERT INTO send_clock VALUES(1,0);
CREATE TABLE outbox (
 id INTEGER PRIMARY KEY AUTOINCREMENT, event_key TEXT NOT NULL UNIQUE,
 method TEXT NOT NULL, payload TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending', due INTEGER NOT NULL,
 attempts INTEGER NOT NULL DEFAULT 0, message_id INTEGER, error_code INTEGER
);

SELECT url,checked_at,error_code FROM feeds;
SELECT title,state,due FROM entries ORDER BY due LIMIT 30;
SELECT id,event_key,state,message_id,error_code FROM outbox ORDER BY id DESC LIMIT 30;
